import { test, expect } from "@playwright/test";
import { readFileSync } from "node:fs";
import { businesses, mockWorkspace } from "./workspace-fixture";
import type { DiscoveryResponse } from "../src/features/discovery/types";

// Generated by isolated backend API test; never a manually assigned compatibility score.
const fixture: DiscoveryResponse = JSON.parse(
  readFileSync("../work/discovery-fixture.json", "utf8"),
);
const demoBusiness = {
  ...businesses[0],
  name: "Fictional Demo — Lagos Pantry Foods",
  country: "Nigeria",
  sector: "Packaged food",
};

test("shared footer hides redundant authenticated action on account and public pages", async ({
  page,
}) => {
  await mockWorkspace(page, [demoBusiness]);
  await page.goto("/account");
  await expect(
    page.getByRole("heading", { name: "Welcome to Kobentra." }),
  ).toBeVisible();
  await expect(
    page.locator("footer").getByRole("link", { name: "Go to my account" }),
  ).toHaveCount(0);
  await expect(
    page.getByRole("link", { name: "My account", exact: true }).first(),
  ).toBeVisible();
  await page
    .getByRole("link", { name: "Platform", exact: true })
    .first()
    .click();
  await expect(page).toHaveURL(/\/platform$/);
  await expect(
    page.locator("footer").getByRole("link", { name: "Go to my account" }),
  ).toHaveCount(0);
});

test("unauthenticated mobile footer keeps signup and sign-in navigation", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.route("**/api/auth/me", (route) =>
    route.fulfill({ status: 401, json: {} }),
  );
  await page.goto("/signin");
  const action = page
    .locator("footer")
    .getByRole("link", { name: "Start your next chapter" });
  await expect(action).toHaveAttribute("href", "/signup");
  await action.scrollIntoViewIfNeeded();
  await expect(action).toBeVisible();
  await expect(
    page.getByRole("link", { name: "Sign in", exact: true }).first(),
  ).toHaveAttribute("href", "/signin");
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= innerWidth,
    ),
  ).toBe(true);
});

test("computed fictional match, explanations, privacy and introduction guard", async ({
  page,
}) => {
  await mockWorkspace(page, [demoBusiness, businesses[1]]);
  await page.route("**/api/businesses/org-a/matches", (route) =>
    route.fulfill({ json: fixture }),
  );
  await page.goto("/workspace/org-a/discover");
  await expect(
    page.locator("footer").getByRole("link", { name: "Go to my account" }),
  ).toHaveCount(0);
  const card = page.getByRole("article", {
    name: fixture.matches[0].partner.name,
  });
  await expect(
    card.getByText("FICTIONAL DEMO BUSINESS", { exact: true }),
  ).toBeVisible();
  await expect(
    card.getByText(String(fixture.matches[0].compatibility.score), {
      exact: true,
    }),
  ).toBeVisible();
  await expect(card.getByText("62.5%", { exact: true })).toBeVisible();
  await expect(card.getByText("unknown", { exact: true })).toHaveCount(2);
  await expect(
    card.getByText("Introduction restricted", { exact: true }),
  ).toBeVisible();
  await expect(card.getByRole("button")).toHaveCount(0);
  await card
    .getByText("Evidence limitations & qualification gaps", { exact: true })
    .click();
  await expect(
    card.getByText(
      "Private assessments are not used for cross-tenant discovery.",
      { exact: true },
    ),
  ).toBeVisible();
  await page.screenshot({
    path: "../work/discovery-desktop.png",
    fullPage: true,
  });
  await page.getByLabel("Active business").selectOption("org-b");
  await expect(
    page.getByRole("article", { name: fixture.matches[0].partner.name }),
  ).toHaveCount(0);
});

test("mobile dark theme, reduced motion and keyboard disclosure", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.emulateMedia({ reducedMotion: "reduce" });
  await mockWorkspace(page, [demoBusiness]);
  await page.route("**/api/businesses/org-a/matches", (route) =>
    route.fulfill({ json: fixture }),
  );
  await page.goto("/workspace/org-a/discover");
  await page.getByRole("button", { name: "Use dark theme" }).click();
  await expect(
    page.locator("footer").getByRole("link", { name: "Go to my account" }),
  ).toHaveCount(0);
  const summary = page.getByText("Evidence limitations & qualification gaps", {
    exact: true,
  });
  await summary.focus();
  await page.keyboard.press("Enter");
  await expect(
    page.getByText(
      "Private assessments are not used for cross-tenant discovery.",
      { exact: true },
    ),
  ).toBeVisible();
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= innerWidth,
    ),
  ).toBe(true);
  await page.screenshot({
    path: "../work/discovery-mobile-dark.png",
    fullPage: true,
  });
});

test("loading, safe error, retry and not-configured state", async ({
  page,
}) => {
  await mockWorkspace(page, [demoBusiness]);
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  let failed = true;
  await page.route("**/api/businesses/org-a/matches", async (route) => {
    await gate;
    if (failed) {
      return route.fulfill({ status: 503, body: "private internal detail" });
    }
    return route.fulfill({
      json: { ...fixture, matches: [], directory_status: "not_configured" },
    });
  });
  await page.goto("/workspace/org-a/discover");
  await expect(page.getByRole("status")).toHaveText("Loading workspace data…");
  release();
  await expect(page.getByRole("alert")).toContainText(
    "Unable to complete this request",
  );
  await expect(page.getByText("private internal detail")).toHaveCount(0);
  failed = false;
  await page.getByRole("button", { name: "Retry", exact: true }).click();
  await expect(
    page.getByRole("heading", {
      name: "Discovery is awaiting publication approval",
    }),
  ).toBeVisible();
});

test("approved empty directory and insufficient evidence never fabricate scores", async ({
  page,
}) => {
  await mockWorkspace(page, [demoBusiness]);
  let empty = true;
  await page.route("**/api/businesses/org-a/matches", (route) =>
    route.fulfill({
      json: {
        ...fixture,
        matches: empty
          ? []
          : [
              {
                ...fixture.matches[0],
                compatibility: {
                  ...fixture.matches[0].compatibility,
                  score: null,
                  sufficient_evidence: false,
                },
              },
            ],
      },
    }),
  );
  await page.goto("/workspace/org-a/discover");
  await expect(
    page.getByRole("heading", { name: "No cross-border partners to show yet" }),
  ).toBeVisible();
  empty = false;
  await page.getByRole("button", { name: "Refresh discovery" }).click();
  await expect(
    page.getByText("Not enough evidence", { exact: true }),
  ).toBeVisible();
  await expect(
    page.getByText("Compatibility / 100", { exact: true }),
  ).toHaveCount(0);
});
